class PricingAdjustmentKind(str, Enum):
    DESCUENTO = "DESCUENTO"
    BONIFICACION = "BONIFICACION"
    CORTESIA = "CORTESIA"


class PricingDecisionStatus(str, Enum):
    SOLICITADA = "SOLICITADA"
    APROBADA = "APROBADA"
    RECHAZADA = "RECHAZADA"
    CANCELADA = "CANCELADA"


@dataclass(frozen=True)
class HistoricalTariffSnapshot:
    tariff_snapshot_id: str
    contract_period_id: str
    classification_reference: Optional[str]
    normal_amount: float
    currency_code: str
    effective_from: str
    effective_to: Optional[str] = None


@dataclass(frozen=True)
class PricingExceptionDecision:
    decision_id: str
    tariff_snapshot_id: str
    adjustment_kind: PricingAdjustmentKind
    status: PricingDecisionStatus
    requested_by_user_id: str
    requested_amount: float
    normal_amount: float
    authorized_amount: Optional[float] = None
    decided_by_user_id: Optional[str] = None
    reason: Optional[str] = None
    evidence_reference: Optional[str] = None
    valid_from: Optional[str] = None
    valid_to: Optional[str] = None


def validate_historical_tariff_snapshot(snapshot: HistoricalTariffSnapshot) -> None:
    for field_name, value in (("tariff_snapshot_id", snapshot.tariff_snapshot_id), ("contract_period_id", snapshot.contract_period_id), ("currency_code", snapshot.currency_code), ("effective_from", snapshot.effective_from)):
        if not str(value or "").strip():
            raise ValueError(f"HistoricalTariffSnapshot requiere {field_name}")
    if snapshot.normal_amount < 0:
        raise ValueError("normal_amount no puede ser negativo")
    if snapshot.effective_to and snapshot.effective_to < snapshot.effective_from:
        raise ValueError("effective_to no puede ser anterior a effective_from")


def validate_pricing_exception_decision(decision: PricingExceptionDecision) -> None:
    for field_name, value in (("decision_id", decision.decision_id), ("tariff_snapshot_id", decision.tariff_snapshot_id), ("requested_by_user_id", decision.requested_by_user_id)):
        if not str(value or "").strip():
            raise ValueError(f"PricingExceptionDecision requiere {field_name}")
    if decision.normal_amount < 0 or decision.requested_amount < 0:
        raise ValueError("Los importes no pueden ser negativos")
    if decision.valid_from and decision.valid_to and decision.valid_to < decision.valid_from:
        raise ValueError("valid_to no puede ser anterior a valid_from")
    if decision.status == PricingDecisionStatus.SOLICITADA:
        if decision.authorized_amount is not None or decision.decided_by_user_id:
            raise ValueError("Una solicitud pendiente no debe tener decision final")
        return
    if decision.status in {PricingDecisionStatus.APROBADA, PricingDecisionStatus.RECHAZADA}:
        if not str(decision.decided_by_user_id or "").strip():
            raise ValueError("Una decision final requiere decided_by_user_id")
        if not str(decision.reason or "").strip():
            raise ValueError("Una decision final requiere reason")
    if decision.status == PricingDecisionStatus.APROBADA:
        if decision.authorized_amount is None:
            raise ValueError("APROBADA requiere authorized_amount")
        if decision.authorized_amount < 0:
            raise ValueError("authorized_amount no puede ser negativo")
    if decision.status == PricingDecisionStatus.RECHAZADA and decision.authorized_amount is not None:
        raise ValueError("RECHAZADA no debe tener authorized_amount")


def pricing_foregone_revenue(decision: PricingExceptionDecision) -> float:
    validate_pricing_exception_decision(decision)
    if decision.status != PricingDecisionStatus.APROBADA:
        return 0.0
    return round(max(float(decision.normal_amount) - float(decision.authorized_amount or 0), 0.0), 2)
